<script setup lang="ts">import { inject, type Ref } from "vue"; import type { AdminUser } from "../../api"; const user = inject<Ref<AdminUser | null>>("adminUser");</script><template><section v-if="user" class="detail-tab"><h2>Datos de usuario</h2><dl><dt>Nombre</dt><dd>{{ user.displayName }}</dd><dt>Email</dt><dd>{{ user.email }}</dd><dt>Rol</dt><dd>{{ user.role }}</dd><dt>Estado</dt><dd>{{ user.active ? 'Activo' : 'Inactivo' }}</dd></dl></section></template>